/* Checksum.ai autogenerated test */
import { init, IVariablesStore } from "@checksum-ai/runtime"
const { test, defineChecksumTest, login, expect, checksumAI } = init()

/*
Things to do:
1. Add a random product name using Date.now() and have the product name include "cktest" to ensure we know it's created by one of our tests. (https://docs.google.com/document/d/1N9XNM8iKTVgUSnRV2ARGi_6lpVo3f2FCaa9pJ_GMU6Q/edit#heading=h.uhj7izteq3od)
2. Save the product name to a variable using the variableStore. Navigate to the product page and verify the product name matches the variable. (https://docs.google.com/document/d/1N9XNM8iKTVgUSnRV2ARGi_6lpVo3f2FCaa9pJ_GMU6Q/edit#heading=h.t045htr4v6ra)
3. Verify the product details match the values used during creation.


When you are done - Experience Checksum Autohealing features
1. Read about auto healing features in the /admin-frontend/checksum/README.md
2. Break the New Product Button Selector. Run the test and see how it autoheals.
3. Remove the New Product Button action and see how Checksum auto heals it
4. Turn off all auto healing features and run the test again. See how the test fails.
5. NOTE: sometimes it's better to turn off auto healing features when editing a test. Makes it easier to spot the changes you need to make.
*/

test(
  defineChecksumTest("Add a product", "78eGZ"),
  async ({
    page,
    variablesStore,
  }: {
    page
    variablesStore: IVariablesStore
  }) => {
    await login(page)
    await page.goto("/", { waitUntil: "domcontentloaded" })
    await checksumAI("Click on products button", () =>
      page
        .checksumSelector("FBnYK")
        .getByRole("link", { name: "Products" })
        .click()
    )
    await checksumAI("Click on new product button", () =>
      page
        .checksumSelector("x2t44")
        .getByRole("button", { name: "New Product" })
        .click()
    )
    variablesStore.titleValue = "New Product"
    await checksumAI("Fill title with random string", async () => {
      await page
        .checksumSelector("J6hvu")
        .getByPlaceholder("Winter Jacket")
        .clear()
      await page
        .checksumSelector("J6hvu")
        .getByPlaceholder("Winter Jacket")
        .pressSequentially(variablesStore.titleValue)
    })
    variablesStore.subtitleValue = "ck-subtitle-todaysdate"
    await checksumAI("Fill subtitle with random string", async () => {
      await page
        .checksumSelector("xSCc4")
        .getByPlaceholder("Warm and cozy...")
        .clear()
      await page
        .checksumSelector("xSCc4")
        .getByPlaceholder("Warm and cozy...")
        .pressSequentially(variablesStore.subtitleValue)
    })
    variablesStore.descriptionValue = "this is a test description"
    await checksumAI(
      'Fill description with "this is a test description"',
      async () => {
        await page
          .checksumSelector("oBOdk")
          .getByPlaceholder("A warm and cozy jacket...")
          .clear()
        await page
          .checksumSelector("oBOdk")
          .getByPlaceholder("A warm and cozy jacket...")
          .pressSequentially(variablesStore.descriptionValue)
      }
    )
    await checksumAI("Click on Publish Product button", () =>
      page
        .checksumSelector("te348")
        .getByRole("button", { name: "Publish product" })
        .click()
    )
    await checksumAI("Click back button", () =>
      page
        .checksumSelector("njoFW")
        .getByRole("button", { name: "Back to Products" })
        .click()
    )
  }
)
